#[derive(Clone, Copy, Debug, PartialEq)]
enum PositionSnap {
    Off,
    Mm1,
    Mm5,
    Mm10,
}
impl PositionSnap {
    fn label(self) -> &'static str {
        match self {
            Self::Off => "Off",
            Self::Mm1 => "1 mm",
            Self::Mm5 => "5 mm",
            Self::Mm10 => "10 mm",
        }
    }
    fn apply(self, value: f64) -> f64 {
        let factor = match self {
            Self::Off => return value,
            Self::Mm1 => 1000.0,
            Self::Mm5 => 200.0,
            Self::Mm10 => 100.0,
        };
        (value * factor).round() / factor
    }
}
