    #[test]
    fn command_search_labels_and_shortcut_follow_the_platform() {
        use egui::{Modifiers, os::OperatingSystem};

        for (os, label, platform_modifier) in [
            (OperatingSystem::Mac, "Commands ⌘K", Modifiers::MAC_CMD),
            (OperatingSystem::Nix, "Commands Ctrl+K", Modifiers::CTRL),
            (OperatingSystem::Windows, "Commands Ctrl+K", Modifiers::CTRL),
        ] {
            let (ctx, mut app) = fixture();
            ctx.set_os(os);
            let output = frame(&ctx, &mut app, 1000., vec![]);
            let toolbar_command = button(&output, label);
            frame(
                &ctx,
                &mut app,
                1000.,
                vec![key(egui::Key::K, Modifiers::COMMAND | platform_modifier)],
            );
            assert!(app.search, "keyboard shortcut for {os:?}");
            frame(
                &ctx,
                &mut app,
                1000.,
                vec![key(egui::Key::Escape, Modifiers::NONE)],
            );
            assert!(!app.search);

            let output = click(&ctx, &mut app, "Edit");
            assert!(
                output
                    .platform_output
                    .accesskit_update
                    .as_ref()
                    .unwrap()
                    .nodes
                    .iter()
                    .any(|(id, node)| {
                        *id != toolbar_command
                            && node.label() == Some(label)
                            && node.supports_action(Action::Click)
                            && !node.is_disabled()
                    }),
                "missing Edit menu command for {os:?}"
            );
        }
    }

    #[test]
    fn frame_garment_fits_visible_rest_and_accepted_positions_without_editing() {
        let ctx = egui::Context::default();
        ctx.enable_accesskit();
        studio_style(&ctx);
        ctx.all_styles_mut(|style| style.animation_time = 0.);
        let mut app = Studio::empty();
        app.session_autosave = None;
        let empty = click(&ctx, &mut app, "View");
        assert!(
            empty
                .platform_output
                .accesskit_update
                .unwrap()
                .nodes
                .iter()
                .any(|(_, node)| { node.label() == Some("Frame garment") && node.is_disabled() })
        );
        frame(
            &ctx,
            &mut app,
            1000.,
            vec![key(egui::Key::Escape, egui::Modifiers::NONE)],
        );
        assert!(app.garment_frame.is_none());
        assert_eq!(app.camera_scale, 270.);

        for origin in [[14., 10.], [38., 36.], [-45., 70.]] {
            app.editor
                .execute(Command::AddRectangle {
                    name: format!("Original panel {}", origin[0]),
                    origin,
                    width: 0.375,
                    height: 0.6,
                })
                .unwrap();
        }
        app.editor
            .execute(Command::SetResolution { metres: 0.08 })
            .unwrap();
        assert!(app.editor.undo());
        app.selected = Some(app.editor.project.pieces[0].id);
        app.hidden_pieces.insert(app.editor.project.pieces[2].id);
        let hidden = app.hidden_pieces.clone();
        let selection = (app.selected, app.selected_curve);
        let mesh = Arc::new(app.editor.project.mesh().unwrap());
        let mut cloth =
            weftforge_core::simulation::create_cloth(&app.editor.project, &mesh).unwrap();
        cloth.step(Default::default(), || false).unwrap();
        assert_ne!(cloth.positions(), mesh.positions);
        let cloth = Arc::new(cloth);
        app.mesh = Some(mesh.clone());
        app.yaw = 0.35;
        app.pitch = 0.22;
        app.camera_scale = 412.;
        app.center = [0.13, 0.77];
        app.scale = 213.;
        let before = format!("{:?}", app.editor);

        let output = frame(&ctx, &mut app, 1000., vec![]);
        frame(
            &ctx,
            &mut app,
            1000.,
            vec![action(numeric(&output, 0.375), Action::Focus, None)],
        );
        frame(&ctx, &mut app, 1000., vec![]);
        frame(
            &ctx,
            &mut app,
            1000.,
            vec![
                key(egui::Key::A, egui::Modifiers::COMMAND),
                egui::Event::Text("1e-".into()),
            ],
        );
        let focus = numeric_focus(&ctx).unwrap();
        let caret = egui::TextEdit::load_state(&ctx, focus)
            .unwrap()
            .cursor
            .char_range();
        app.draft.as_mut().unwrap().dimensions.as_mut().unwrap()[1] = 0.65;
        let pending = app.draft.as_ref().unwrap().commands(&app.editor.project);

        let mut rest_frame = None;
        for search in [false, true] {
            app.cloth = search.then(|| cloth.clone());
            let id = if search {
                app.open_command_search(&ctx);
                app.query = "frame garment".into();
                frame(&ctx, &mut app, 1000., vec![]);
                let output = frame(&ctx, &mut app, 1000., vec![]);
                super::tests::command_search_action(&output, "Frame garment")
            } else {
                button(&click(&ctx, &mut app, "View"), "Frame garment")
            };
            // Resize between showing the View action and activating it.
            let height = if search { 1000. } else { 650. };
            frame(
                &ctx,
                &mut app,
                height,
                vec![action(id, Action::Click, None)],
            );
            frame(&ctx, &mut app, height, vec![]);
            let canvas = ctx.read_response(app.garment_canvas.unwrap()).unwrap().rect;
            let inset = canvas.shrink(28.);
            let mut fitted_bounds = Rect::NOTHING;
            let positions = if search {
                cloth.positions()
            } else {
                mesh.positions.as_slice()
            };
            for (&point, piece) in positions.iter().zip(&mesh.piece_ids) {
                if !hidden.contains(piece) {
                    fitted_bounds.extend_with(app.project3(point, canvas).0);
                }
            }
            assert!(inset.expand(0.002).contains_rect(fitted_bounds));
            assert!((fitted_bounds.center() - canvas.center()).length() <= 0.002);
            assert!(
                (fitted_bounds.width() - inset.width()).abs() <= 0.002
                    || (fitted_bounds.height() - inset.height()).abs() <= 0.002
            );
            let fitted = app.garment_frame.unwrap();
            assert!(fitted.scale < MIN_CAMERA_SCALE);
            if search {
                assert_ne!(rest_frame.unwrap(), fitted.target);
                assert!(Arc::ptr_eq(app.cloth.as_ref().unwrap(), &cloth));
            } else {
                rest_frame = Some(fitted.target);
                assert!(app.cloth.is_none());
            }
            frame(
                &ctx,
                &mut app,
                height,
                vec![egui::Event::PointerMoved(canvas.center())],
            );
            assert_eq!(app.camera_scale, fitted.scale);
            assert_eq!([app.yaw, app.pitch], [0.35, 0.22]);
            assert_eq!((app.center, app.scale), ([0.13, 0.77], 213.));
            assert_eq!((app.selected, app.selected_curve), selection);
            assert_eq!(app.hidden_pieces, hidden);
            assert_eq!(
                app.draft.as_ref().unwrap().commands(&app.editor.project),
                pending
            );
            assert_eq!(numeric_focus(&ctx), Some(focus));
            assert_eq!(
                ctx.data_mut(|data| data.get_temp::<String>(focus))
                    .as_deref(),
                Some("1e-")
            );
            assert_eq!(
                egui::TextEdit::load_state(&ctx, focus)
                    .unwrap()
                    .cursor
                    .char_range(),
                caret
            );
            assert_eq!(format!("{:?}", app.editor), before);
            assert!(Arc::ptr_eq(app.mesh.as_ref().unwrap(), &mesh));
            assert!(!app.search && !app.dirty && !app.needs_mesh && app.job.is_none());
        }

        assert!(app.fit_garment(Rect::ZERO).is_none());
        let canvas = ctx.read_response(app.garment_canvas.unwrap()).unwrap().rect;
        app.hidden_pieces.extend(mesh.piece_ids.iter().copied());
        assert!(app.fit_garment(canvas).is_none());
    }

    #[test]
    fn standard_camera_views_use_y_up_axes_and_preserve_the_scene() {
        let (ctx, mut app) = fixture();
        app.editor
            .execute(Command::AddRectangle {
                name: "Hidden panel".into(),
                origin: [2., 1.],
                width: 0.3,
                height: 0.6,
            })
            .unwrap();
        app.hidden_pieces
            .insert(app.editor.project.pieces.last().unwrap().id);
        let hidden = app.hidden_pieces.clone();
        let mesh = Arc::new(app.editor.project.mesh().unwrap());
        let cloth =
            Arc::new(weftforge_core::simulation::create_cloth(&app.editor.project, &mesh).unwrap());
        app.mesh = Some(mesh.clone());
        app.cloth = Some(cloth.clone());
        app.camera_scale = 412.;
        app.center = [0.13, 0.77];
        app.scale = 213.;
        app.set_tool(Tool::Polygon);
        app.polygon = vec![[0., 0.], [0.1, 0.]];
        let gesture = app.polygon.clone();
        let selection = (app.selected, app.selected_curve);
        let before = format!("{:?}", app.editor);

        let output = frame(&ctx, &mut app, 1000., vec![]);
        frame(
            &ctx,
            &mut app,
            1000.,
            vec![action(numeric(&output, 0.4), Action::Focus, None)],
        );
        frame(&ctx, &mut app, 1000., vec![]);
        frame(
            &ctx,
            &mut app,
            1000.,
            vec![
                key(egui::Key::A, egui::Modifiers::COMMAND),
                egui::Event::Text("1e-".into()),
            ],
        );
        let focus = numeric_focus(&ctx).unwrap();
        let caret = egui::TextEdit::load_state(&ctx, focus)
            .unwrap()
            .cursor
            .char_range();
        app.draft.as_mut().unwrap().dimensions.as_mut().unwrap()[1] = 0.65;
        let draft = app.draft.as_ref().unwrap().commands(&app.editor.project);

        let choose = |app: &mut Studio, search, label: &str| {
            let id = if search {
                app.open_command_search(&ctx);
                app.query = label.to_ascii_lowercase();
                frame(&ctx, app, 1000., vec![]);
                let output = frame(&ctx, app, 1000., vec![]);
                super::tests::command_search_action(&output, label)
            } else {
                button(&click(&ctx, app, "View"), label)
            };
            frame(&ctx, app, 1000., vec![action(id, Action::Click, None)]);
            frame(&ctx, app, 1000., vec![]);
            assert!(!app.search);
        };
        let rect = Rect::from_min_size(Pos2::ZERO, Vec2::new(1200., 1000.));
        let center = [0., 1., 0.];
        // One metre along X, Y and Z, in (screen right, screen down, depth) order.
        let axes = [
            ("Front view", [[1., 0., 0.], [0., -1., 0.], [0., 0., 1.]]),
            ("Back view", [[-1., 0., 0.], [0., -1., 0.], [0., 0., -1.]]),
            ("Left view", [[0., 0., -1.], [0., -1., 0.], [1., 0., 0.]]),
            ("Right view", [[0., 0., 1.], [0., -1., 0.], [-1., 0., 0.]]),
            ("Top view", [[1., 0., 0.], [0., 0., 1.], [0., 1., 0.]]),
            ("Bottom view", [[1., 0., 0.], [0., 0., -1.], [0., -1., 0.]]),
        ];
        for search in [false, true] {
            for (label, axes) in axes {
                choose(&mut app, search, label);
                let (origin, depth_origin) = app.project3(center, rect);
                for (axis, expected) in axes.into_iter().enumerate() {
                    let mut point = center;
                    point[axis] += 1.;
                    let (screen, depth) = app.project3(point, rect);
                    let projected = (screen - origin) / app.camera_scale;
                    let actual = [projected.x, projected.y, depth - depth_origin];
                    for (measured, expected) in actual.into_iter().zip(expected) {
                        assert!(
                            (measured - expected).abs() <= 1.0e-6,
                            "{label}, axis {axis}: {actual:?}"
                        );
                    }
                }
            }
            choose(&mut app, search, "Default orbit view");
            assert_eq!([app.yaw, app.pitch], [-0.45, 0.12]);
            assert_eq!(app.camera_scale, 412.);
            assert_eq!((app.center, app.scale), ([0.13, 0.77], 213.));
            assert_eq!(app.hidden_pieces, hidden);
            assert_eq!((app.selected, app.selected_curve), selection);
            assert!(app.tool == Tool::Polygon && app.polygon == gesture);
            assert_eq!(
                app.draft.as_ref().unwrap().commands(&app.editor.project),
                draft
            );
            assert_eq!(numeric_focus(&ctx), Some(focus));
            assert_eq!(
                ctx.data_mut(|data| data.get_temp::<String>(focus))
                    .as_deref(),
                Some("1e-")
            );
            assert_eq!(
                egui::TextEdit::load_state(&ctx, focus)
                    .unwrap()
                    .cursor
                    .char_range(),
                caret
            );
            assert_eq!(format!("{:?}", app.editor), before);
            assert!(!app.dirty && !app.needs_mesh && app.job.is_none());
            assert!(Arc::ptr_eq(app.mesh.as_ref().unwrap(), &mesh));
            assert!(Arc::ptr_eq(app.cloth.as_ref().unwrap(), &cloth));
        }
    }

