    #[test]
    fn pattern_fields_have_unique_accessible_names_and_fit_the_narrow_dock() {
        fn named(
            node: &egui::accesskit::Node,
            nodes: &[(NodeId, egui::accesskit::Node)],
            name: &str,
        ) -> bool {
            node.label() == Some(name)
                || node.labelled_by().iter().any(|label| {
                    nodes.iter().any(|(id, node)| {
                        id == label && (node.label() == Some(name) || node.value() == Some(name))
                    })
                })
        }
        fn fits(node: &egui::accesskit::Node, dock: Rect) {
            let bounds = node.bounds().unwrap();
            assert!(
                bounds.x0 >= f64::from(dock.left()) && bounds.x1 <= f64::from(dock.right()),
                "outside dock {dock:?}: {bounds:?}"
            );
            assert!(
                bounds.y0 >= f64::from(dock.top()) && bounds.y1 <= f64::from(dock.bottom()),
                "outside dock {dock:?}: {bounds:?}"
            );
        }
        for (width, dock_width) in [(1000., 248.), (1640., 292.)] {
            let ctx = egui::Context::default();
            ctx.enable_accesskit();
            studio_style(&ctx);
            ctx.all_styles_mut(|style| style.animation_time = 0.);
            let mut app = Studio::empty();
            app.session_autosave = None;
            let draw = |app: &mut Studio| {
                ctx.run_ui(
                    egui::RawInput {
                        screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(width, 1000.))),
                        ..Default::default()
                    },
                    |ui| eframe::App::ui(app, ui, &mut eframe::Frame::_new_kittest()),
                )
            };
            let before = format!("{:?}", app.editor);
            draw(&mut app);
            let output = draw(&mut app);
            let dock =
                egui::containers::panel::PanelState::load(&ctx, egui::Id::new("studio-properties"))
                    .unwrap()
                    .outer_rect;
            assert_eq!(dock.width(), dock_width);
            let nodes = &output
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes;
            let names: Vec<_> = nodes
                .iter()
                .filter(|(_, node)| {
                    node.role() == egui::accesskit::Role::TextInput
                        && named(node, nodes, "Pattern name")
                })
                .collect();
            assert_eq!(names.len(), 1);
            assert_eq!(names[0].1.value(), Some("Pattern 1"));
            fits(&names[0].1, dock);
            assert_eq!(format!("{:?}", app.editor), before);

            app.editor
                .execute(Command::AddRectangle {
                    name: "Equal values".into(),
                    origin: [0.; 2],
                    width: 0.4,
                    height: 0.4,
                })
                .unwrap();
            let piece = app.editor.project.pieces[0].id;
            app.editor
                .execute(Command::SetPlacement {
                    piece,
                    placement: weftforge_core::Placement {
                        translation: [0.4; 3],
                        rotation: [0.4; 3],
                    },
                })
                .unwrap();
            app.editor
                .execute(Command::SetGrain { piece, angle: 0.4 })
                .unwrap();
            app.editor
                .execute(Command::SetResolution { metres: 0.08 })
                .unwrap();
            assert!(app.editor.undo());
            app.selected = Some(piece);
            let before = format!("{:?}", app.editor);
            draw(&mut app);
            let output = draw(&mut app);
            let nodes = &output
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes;
            let mut fields = Vec::new();
            for name in [
                "Pattern width m",
                "Pattern height m",
                "Translation X m",
                "Translation Y m",
                "Translation Z m",
                "Rotation X radians",
                "Rotation Y radians",
                "Rotation Z radians",
                "Warp angle radians",
            ] {
                let matches: Vec<_> = nodes
                    .iter()
                    .filter(|(_, node)| {
                        node.numeric_value().is_some()
                            && !node.is_disabled()
                            && named(node, nodes, name)
                    })
                    .collect();
                assert_eq!(matches.len(), 1, "unique field {name}");
                assert_eq!(matches[0].1.numeric_value(), Some(0.4), "{name}");
                assert!(matches[0].1.supports_action(Action::Focus));
                assert!(!fields.contains(&matches[0].0), "distinct target {name}");
                fields.push(matches[0].0);
                fits(&matches[0].1, dock);
            }
            assert_eq!(fields.len(), 9);
            assert_eq!(format!("{:?}", app.editor), before);
            assert!(!app.dirty && !app.needs_mesh && app.job.is_none() && app.editor.can_redo());
        }
    }

    #[test]
    fn tabs_and_contextual_groups_reach_real_controls_without_authoring() {
        let (ctx, mut app) = fixture();
        let before = format!("{:?}", app.editor);
        for (tab, labels) in [
            ("Pattern", vec!["Warp angle radians", "Delete selected"]),
            (
                "Fabric",
                vec![
                    "Mass/area kg/m²",
                    "Warp stiffness N/m",
                    "Weft stiffness N/m",
                    "Bend N·m",
                ],
            ),
            (
                "Simulation",
                vec![
                    "Mesh edge length m",
                    "Iterations / substeps",
                    "Simulation settings",
                ],
            ),
        ] {
            let output = click(&ctx, &mut app, tab);
            let nodes = &output
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes;
            for label in labels
                .iter()
                .copied()
                .chain(["Scene", "Context panel · #2"])
            {
                assert!(nodes.iter().any(|(_, node)| node.label() == Some(label) || node.value() == Some(label)), "missing {label}");
            }
            if tab == "Fabric" {
                for (label, value) in labels.iter().zip([0.18, 400., 400., 0.003]) {
                    let label_id = nodes
                        .iter()
                        .find(|(_, node)| {
                            node.label() == Some(*label) || node.value() == Some(*label)
                        })
                        .unwrap()
                        .0;
                    let mut fields = nodes.iter().filter(|(_, node)| {
                        node.numeric_value().is_some()
                            && node.labelled_by() == std::slice::from_ref(&label_id)
                    });
                    let (_, field) = fields
                        .next()
                        .unwrap_or_else(|| panic!("missing Fabric field {label}"));
                    assert!(fields.next().is_none(), "ambiguous Fabric field {label}");
                    assert_eq!(field.numeric_value(), Some(value), "Fabric field {label}");
                }
            }
            for label in ["Pattern", "Fabric", "Simulation"] {
                let id = button(&output, label);
                let bounds = nodes
                    .iter()
                    .find(|(node, _)| *node == id)
                    .unwrap()
                    .1
                    .bounds()
                    .unwrap();
                assert!(
                    bounds.x0 >= 0. && bounds.y0 >= 0. && bounds.x1 <= 1640. && bounds.y1 <= 1000.
                );
            }
        }
        click(&ctx, &mut app, "Pattern");
        let output = click(&ctx, &mut app, "Create pattern");
        for label in [
            "Add rectangle",
            "Add ellipse",
            "Add hole…",
            "Internal line…",
            "Add polygon point",
        ] {
            button(&output, label);
        }
        click(&ctx, &mut app, "Fabric");
        let output = click(&ctx, &mut app, "M:N sewing");
        button(&output, "Confirm A (Enter)");
        button(&output, "Reverse paired edge");
        let output = click(&ctx, &mut app, "Pattern");
        let pattern = button(&output, "Pattern");
        frame(
            &ctx,
            &mut app,
            1000.,
            vec![action(pattern, Action::Focus, None)],
        );
        for label in ["Fabric", "Simulation"] {
            frame(
                &ctx,
                &mut app,
                1000.,
                vec![key(egui::Key::Tab, egui::Modifiers::NONE)],
            );
            let output = frame(&ctx, &mut app, 1000., vec![]);
            let tab = button(&output, label);
            assert_eq!(
                ctx.memory(|memory| memory.focused())
                    .unwrap()
                    .accesskit_id(),
                tab
            );
            frame(
                &ctx,
                &mut app,
                1000.,
                vec![key(egui::Key::Enter, egui::Modifiers::NONE)],
            );
            assert_eq!(app.properties_tab.label(), label);
            assert_eq!(
                ctx.memory(|memory| memory.focused())
                    .unwrap()
                    .accesskit_id(),
                tab
            );
        }
        assert_eq!(format!("{:?}", app.editor), before);
        assert!(!app.dirty && app.editor.can_redo());
    }

    #[test]
    fn tab_switches_suspend_numeric_focus_and_restore_raw_text_caret_and_draft_on_refocus() {
        for source in [
            PropertiesTab::Pattern,
            PropertiesTab::Fabric,
            PropertiesTab::Simulation,
        ] {
            for raw in ["0.4500", "1e-", "NaN"] {
                let (ctx, mut app) = fixture();
                let output = click(&ctx, &mut app, source.label());
                let value = match source {
                    PropertiesTab::Pattern => 0.4,
                    PropertiesTab::Fabric => {
                        app.editor
                            .project
                            .material(app.editor.project.pieces[0].material)
                            .unwrap()
                            .areal_density
                    }
                    PropertiesTab::Simulation => app.editor.project.resolution,
                };
                let field = numeric(&output, value);
                frame(
                    &ctx,
                    &mut app,
                    1000.,
                    vec![action(field, Action::Focus, None)],
                );
                frame(&ctx, &mut app, 1000., vec![]);
                frame(
                    &ctx,
                    &mut app,
                    1000.,
                    vec![
                        key(egui::Key::A, egui::Modifiers::COMMAND),
                        egui::Event::Text(raw.into()),
                    ],
                );
                frame(
                    &ctx,
                    &mut app,
                    1000.,
                    vec![key(egui::Key::ArrowLeft, egui::Modifiers::NONE)],
                );
                let focused = numeric_focus(&ctx).unwrap();
                let caret = egui::TextEdit::load_state(&ctx, focused)
                    .unwrap()
                    .cursor
                    .char_range();
                let before = format!("{:?}", app.editor);
                let pending = format!(
                    "{:?}",
                    app.draft.as_ref().unwrap().commands(&app.editor.project)
                );
                let target = if source == PropertiesTab::Fabric {
                    "Pattern"
                } else {
                    "Fabric"
                };
                let output = frame(&ctx, &mut app, 1000., vec![]);
                let tab = button(&output, target);
                let bounds = output
                    .platform_output
                    .accesskit_update
                    .as_ref()
                    .unwrap()
                    .nodes
                    .iter()
                    .find(|(id, _)| *id == tab)
                    .unwrap()
                    .1
                    .bounds()
                    .unwrap();
                let pos = Pos2::new(
                    ((bounds.x0 + bounds.x1) * 0.5) as f32,
                    ((bounds.y0 + bounds.y1) * 0.5) as f32,
                );
                for pressed in [true, false] {
                    frame(
                        &ctx,
                        &mut app,
                        1000.,
                        vec![
                            egui::Event::PointerMoved(pos),
                            egui::Event::PointerButton {
                                pos,
                                button: egui::PointerButton::Primary,
                                pressed,
                                modifiers: egui::Modifiers::NONE,
                            },
                        ],
                    );
                }
                for _ in 0..4 {
                    frame(&ctx, &mut app, 1000., vec![]);
                }
                assert!(
                    numeric_focus(&ctx).is_none(),
                    "hidden editor kept keyboard focus"
                );
                assert_eq!(format!("{:?}", app.editor), before);
                assert_eq!(
                    format!(
                        "{:?}",
                        app.draft.as_ref().unwrap().commands(&app.editor.project)
                    ),
                    pending
                );
                let navigation = frame(&ctx, &mut app, 1000., vec![]);
                let tab = button(&navigation, source.label());
                frame(
                    &ctx,
                    &mut app,
                    1000.,
                    vec![action(tab, Action::Focus, None)],
                );
                frame(
                    &ctx,
                    &mut app,
                    1000.,
                    vec![key(egui::Key::Enter, egui::Modifiers::NONE)],
                );
                frame(&ctx, &mut app, 1000., vec![]);
                assert_eq!(
                    ctx.memory(|memory| memory.focused())
                        .unwrap()
                        .accesskit_id(),
                    tab
                );
                assert!(
                    numeric_focus(&ctx).is_none(),
                    "showing a section stole keyboard focus"
                );
                frame(
                    &ctx,
                    &mut app,
                    1000.,
                    vec![action(field, Action::Focus, None)],
                );
                for _ in 0..4 {
                    frame(&ctx, &mut app, 1000., vec![]);
                }
                assert_eq!(numeric_focus(&ctx), Some(focused));
                assert_eq!(
                    ctx.data_mut(|data| data.get_temp::<String>(focused))
                        .as_deref(),
                    Some(raw)
                );
                assert_eq!(
                    egui::TextEdit::load_state(&ctx, focused)
                        .unwrap()
                        .cursor
                        .char_range(),
                    caret
                );
                assert_eq!(
                    format!(
                        "{:?}",
                        app.draft.as_ref().unwrap().commands(&app.editor.project)
                    ),
                    pending
                );
                assert_eq!(format!("{:?}", app.editor), before);
                assert!(!app.dirty && app.editor.can_redo());
            }
        }
    }

